"""Tests for the Game of Life engine and pattern library.

Run with:  python -m pytest gol  (or)  python gol/test_gol.py
"""

import sys
import os

sys.path.insert(0, os.path.dirname(__file__))

from engine import step
from patterns import build, PERIODS
from render import render_str


def run_period(seed, limit, period):
    """Return True if the pattern repeats with the given period <= limit."""
    seen = {frozenset(seed): 0}
    universe = seed
    for gen in range(1, limit + 1):
        universe = step(universe)
        if universe == seed:
            return gen == period
        seen.setdefault(frozenset(universe), gen)
    return False


def test_block_stays_stable():
    assert step(build("block")) == build("block")


def test_beehive_stays_stable():
    assert step(build("beehive")) == build("beehive")


def test_blinker_period_2():
    blinker = build("blinker")
    assert step(blinker) != blinker            # horizontal -> vertical
    assert step(step(blinker)) == blinker      # and back


def test_toad_period_2():
    assert run_period(build("toad"), 2, 2)


def test_pulsar_period_3():
    assert run_period(build("pulsar"), 6, 3)


def test_glider_moves_diagonally():
    uni = build("glider")
    uni = step(step(step(step(uni))))          # one full period
    # Box shifted down-right by (1, 1), same shape.
    shifted = set((x + 1, y + 1) for x, y in build("glider"))
    assert uni == shifted


def test_glider_period_4_shape():
    # After 4 generations it has moved but is identical in shape.
    shape0 = build("glider")
    shape4 = step(step(step(step(shape0))))
    assert len(shape4) == len(shape0)
    assert shape4 == set((x + 1, y + 1) for x, y in shape0)


def test_lwss_period_4():
    assert run_period(build("lwss"), 8, 4)


def test_gosper_gun_emits_and_recovers():
    # Over 40 generations the gun emits ~1 glider and returns to its exact
    # starting configuration (the emitted glider escapes and never interferes).
    assert run_period(build("gosper-gun"), 60, 30)


def test_every_declared_period_matches():
    # The advertised PERIODS table should actually hold for each pattern.
    for name, period in PERIODS.items():
        seed = build(name)
        if name in ("glider", "lwss"):
            assert run_period(seed, period * 2, period)
        else:
            assert run_period(seed, period * 2 + 1, period)


def test_dead_cell_with_three_neighbours_is_born():
    # A glider's leading cell gets born between generations; just check the
    # simple case: three live in an L shape produce the fourth cell.
    seed = {(0, 0), (1, 0), (0, 1)}
    next_ = step(seed)
    assert (1, 1) in next_


def test_render_layout_matches_pattern_spec():
    # If we render a pattern within its own bounding box we recover the spec.
    glider = build("glider")
    out = render_str(glider, 3, 3)
    assert out == ".#.\n..#\n###"


def test_empty_universe_stays_empty():
    assert step(set()) == set()


def test_bounding_box_grows_with_population():
    # A blinker should consume exactly 3 cells at all times.
    for _ in range(10):
        assert len(set(step(build("blinker")))) == 3


if __name__ == "__main__":
    import traceback
    failures = 0
    for name, fn in sorted(globals().items()):
        if name.startswith("test_") and callable(fn):
            try:
                fn()
                print(f"PASS {name}")
            except Exception:
                failures += 1
                print(f"FAIL {name}")
                traceback.print_exc()
    print(f"\n{failures} failure(s)")
    sys.exit(1 if failures else 0)

